data.minimal_example:
ImplicitlyAnimatedList<MyGenericType>(
  items: items,
  areItemsTheSame: (a, b) => a.id == b.id,
  itemBuilder: (context, animation, item, index) {
    return SizeFadeTransition(
      sizeFraction: 0.7,
      curve: Curves.easeInOut,
      animation: animation,
      child: Text(item.name),
    );
  },
);
